// ─── DAILY FOLLOW-UP DIGEST BUILDER ──────────────────────────────────────
//
// Finds leads where Next Follow-Up Date = today (or overdue)
// and no reply has been received.
// Builds a plain-text digest to email to yourself.
//
// This workflow does NOT send outreach emails.
// It tells YOU who to follow up with today.

const items = $input.all();
const today = new Date();
today.setHours(0, 0, 0, 0);
const todayStr = today.toISOString().split('T')[0];

// ── Closed statuses — skip these completely ──────────────────────────────
const closedStatuses = [
  'Booked',
  'Not Interested',
  'Lost',
  'Park - 90 Days'
];

// ── Categorize leads ─────────────────────────────────────────────────────
const dueToday = [];    // Follow-up date = today
const overdue = [];     // Follow-up date < today (missed days)
const newReplies = [];  // Reply received but not yet in Replied/Interested/Booked status

for (const item of items) {
  const lead = item.json;

  // Skip empty rows
  if (!lead['Business Name'] || !lead['Email']) continue;

  const status = lead['Status'] || 'New Lead';
  const replyReceived = lead['Reply Received'] === 'TRUE' || lead['Reply Received'] === true;
  const nextFollowUpStr = lead['Next Follow-Up Date'];

  // Skip closed statuses
  if (closedStatuses.includes(status)) continue;

  // Flag leads that replied but status hasn't been updated yet
  if (replyReceived && !['Replied', 'Interested', 'Booked', 'Not Interested', 'Lost'].includes(status)) {
    newReplies.push(lead);
    continue;
  }

  // Skip if already replied (no follow-up needed)
  if (replyReceived) continue;

  // Check if follow-up is due
  if (!nextFollowUpStr) continue;

  const nextFollowUpDate = new Date(nextFollowUpStr);
  nextFollowUpDate.setHours(0, 0, 0, 0);

  const diffDays = Math.floor((today - nextFollowUpDate) / (1000 * 60 * 60 * 24));

  if (diffDays === 0) {
    dueToday.push({ ...lead, _daysOverdue: 0 });
  } else if (diffDays > 0) {
    overdue.push({ ...lead, _daysOverdue: diffDays });
  }
}

// ── Sort overdue by how late they are ────────────────────────────────────
overdue.sort((a, b) => b._daysOverdue - a._daysOverdue);

// ── Build the digest email ───────────────────────────────────────────────
const dateDisplay = today.toLocaleDateString('en-US', {
  weekday: 'long', year: 'numeric', month: 'long', day: 'numeric'
});

let digest = `OUTREACH FOLLOW-UP DIGEST — ${dateDisplay}\n`;
digest += `${'='.repeat(60)}\n\n`;

if (newReplies.length > 0) {
  digest += `⚡ REPLIES RECEIVED (respond today):\n`;
  digest += `-`.repeat(40) + `\n`;
  for (const lead of newReplies) {
    digest += `• ${lead['Business Name']} (${lead['First Name'] || lead['Contact Name']})\n`;
    digest += `  Email: ${lead['Email']}\n`;
    digest += `  Reply summary: ${lead['Reply Summary'] || '(not yet logged)'}\n`;
    digest += `  Status: ${lead['Status']}\n\n`;
  }
}

if (dueToday.length > 0) {
  digest += `📬 FOLLOW-UPS DUE TODAY (${dueToday.length}):\n`;
  digest += `-`.repeat(40) + `\n`;
  for (const lead of dueToday) {
    const step = lead['Status'];
    const lastContact = lead['Last Contact Date'] || lead['Initial Email Date'] || 'unknown';
    digest += `• ${lead['Business Name']} (${lead['First Name'] || lead['Contact Name']}) — ${lead['Industry']}\n`;
    digest += `  Email: ${lead['Email']}\n`;
    digest += `  Stage: ${step}\n`;
    digest += `  Last contact: ${lastContact}\n`;
    digest += `  Personalization: ${lead['Personalization Note'] || '(none logged)'}\n\n`;
  }
} else {
  digest += `📬 FOLLOW-UPS DUE TODAY: None\n\n`;
}

if (overdue.length > 0) {
  digest += `⚠ OVERDUE FOLLOW-UPS (${overdue.length}) — action needed:\n`;
  digest += `-`.repeat(40) + `\n`;
  for (const lead of overdue) {
    digest += `• ${lead['Business Name']} — ${lead['_daysOverdue']} day(s) overdue\n`;
    digest += `  Stage: ${lead['Status']} | Email: ${lead['Email']}\n\n`;
  }
}

// ── Summary line ─────────────────────────────────────────────────────────
const totalActions = newReplies.length + dueToday.length + overdue.length;
digest += `${'='.repeat(60)}\n`;
digest += `TOTAL ACTIONS TODAY: ${totalActions}\n`;
digest += `  Replies to handle: ${newReplies.length}\n`;
digest += `  Follow-ups to send: ${dueToday.length}\n`;
digest += `  Overdue (catch up): ${overdue.length}\n`;
digest += `\nOpen Google Sheets to begin: [your spreadsheet URL here]\n`;

return [{
  json: {
    digest,
    totalActions,
    dueToday: dueToday.length,
    overdue: overdue.length,
    newReplies: newReplies.length,
    hasItems: totalActions > 0
  }
}];
